<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useRouter} from 'vue-router'
import {useGuest} from '../stores/guest'
import {api,requestKey} from '../api/client'
import type {Family,Mode,TrainingSession} from '../types'
import FamilyMark from '../components/FamilyMark.vue'
const guest=useGuest(),router=useRouter(),busy=ref(false),error=ref(''),due=ref(0),attempts=ref<number|null>(null)
const descriptions:Record<Family,string>={dependencies:'Follow the connections. Find what must come first.',logic:'Test the statements. Make every role consistent.',ordering:'Build an order. Separate certainty from possibility.',induction:'Find a rule that fits. Test it against the evidence.',hypothesis:'Ask better questions. Narrow the possibilities.'}
async function start(mode:Mode='mixed',family?:Family){if(busy.value)return;busy.value=true;error.value='';try{const s=await api<TrainingSession>('/sessions','POST',{mode,...(family?{family}:{})},requestKey());await guest.refresh();await router.push('/train/'+s.id)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{try{due.value=(await api<{next_session:number}>('/reviews/due')).next_session;const p=await api<{practice:{independent:number;assisted:number}[]}>('/progress');attempts.value=p.practice.reduce((n,r)=>n+r.independent+r.assisted,0)}catch(e){error.value=(e as Error).message}})
</script>
<template>
 <div class="eyebrow"><span class="tiny-square"></span> THE REASONING NOTEBOOK <span class="edition">VOL. 01 / BEGIN WHERE YOU ARE</span></div>
 <section class="welcome"><div><h1>A little practice.<br>A different way to <span class="underline-yellow">think.</span></h1><p class="lead">Practice reasoning strategies.<br>See what transfers.</p><p class="welcome-copy">Five ways to work through the unfamiliar. Make a prediction,<br class="desktop-only"> test your reasoning, and learn from what happens next.</p><div class="actions"><button class="primary" :disabled="busy" @click="start()">Start training <span>↗</span></button><button class="text-button" :disabled="busy" @click="start('check')">Take a baseline →</button></div><p class="micro">8 PROBLEMS · APPROX. 10–15 MIN · NO TIMER.</p></div>
 <div class="notebook-figure" aria-hidden="true"><div class="figure-caption">01 / FOLLOW A THOUGHT</div><svg viewBox="0 0 310 235" fill="none"><defs><marker id="hero-arrow" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto"><path d="M1 1l5 3-5 3" stroke="var(--ink)"/></marker></defs><path d="M65 60C145 60 100 160 165 160M65 60L240 63M165 160C220 160 220 93 240 85" stroke="var(--ink)" stroke-width="1.5" marker-end="url(#hero-arrow)"/><circle cx="52" cy="60" r="22" fill="var(--surface)" stroke="var(--ink)"/><circle cx="166" cy="164" r="25" fill="var(--yellow)" stroke="var(--ink)"/><circle cx="248" cy="62" r="22" fill="var(--surface)" stroke="var(--ink)"/><text x="52" y="66" text-anchor="middle">A</text><text class="highlight-node-label" x="166" y="170" text-anchor="middle">B</text><text x="248" y="68" text-anchor="middle">C</text><path d="M27 205H280" stroke="var(--line)"/><text x="28" y="226" font-size="10" fill="var(--muted)">notice → test → understand</text><path d="M145 123l13-7M149 135l17-2" stroke="var(--muted)"/></svg><span class="figure-note">What follows from what?</span></div>
 </section>
 <div v-if="error" role="alert" class="error">{{error}}</div>
 <section v-if="guest.me?.sessions.length" class="resume-strip"><div><span class="tiny-square"></span> An open page <p>Your {{guest.me.sessions[0]?.mode}} session is saved.</p></div><RouterLink class="button" :to="'/train/'+guest.me.sessions[0]?.id">Resume session →</RouterLink></section>
 <section class="practice-section"><div class="section-heading"><h2>Choose a way to reason</h2><span>FIVE FAMILIES / FOUR LEVELS EACH</span></div><div class="family-grid"><button v-for="(f,i) in guest.families" :key="f.id" class="family-card" :disabled="busy" @click="start('focus',f.id)"><div class="card-top"><span>0{{i+1}}</span><span class="card-arrow">↗</span></div><FamilyMark :family="f.id"/><h3>{{f.name}}</h3><p>{{descriptions[f.id]}}</p><div class="card-bottom"><span>6 PROBLEMS</span><span>LEVEL {{guest.me?.levels[f.id]??1}}</span></div></button></div></section>
 <section class="lower-grid"><div class="notebook-note"><span class="eyebrow">YOUR NEXT PAGE</span><h3>{{due?'A thought worth revisiting.':attempts?'Keep the thread going.':'Every notebook starts somewhere.'}}</h3><p>{{due?`${due} review item${due===1?'':'s'} ready for a fresh related example in your next session.`:attempts?`${attempts} practice attempts saved. Find your reasoning and worked explanations in Review.`:'No attempts yet. Your first session will give you something to build on.'}}</p><RouterLink v-if="attempts" to="/review">Open your review →</RouterLink><span v-else class="micro">YOUR PROGRESS WILL APPEAR HERE.</span></div><div class="measurement-note"><span class="eyebrow">PRACTICE ≠ PROOF OF TRANSFER</span><h3>Put your strategies to the test.</h3><p>Checks keep difficulty fixed. A separate exploratory probe changes the presentation. See each result for what it measures.</p><button class="text-button" :disabled="busy" @click="start('probe')">Try a presentation probe →</button></div></section>
</template>
